    public static Parameters parse(String operation,JsonNode value) throws java.io.IOException {
        ObjectMapper json=new ObjectMapper().enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
        // 模型参数不接收内部类型标记；只由已验证的operation选择类型。
        if(!value.isObject()||value.has("_operation"))throw new IllegalArgumentException("browser_parameters_invalid");
        var typed=value.deepCopy(); ((com.fasterxml.jackson.databind.node.ObjectNode)typed).put("_operation",operation);
        return switch(operation) {
            case "navigate" -> json.treeToValue(typed,NavigateParameters.class);
            case "navigate-back" -> json.treeToValue(typed,NavigateBackParameters.class);
            case "navigate-forward" -> json.treeToValue(typed,NavigateForwardParameters.class);
            case "reload" -> json.treeToValue(typed,ReloadParameters.class);
            case "screenshot" -> json.treeToValue(typed,ScreenshotParameters.class);
            case "snapshot" -> json.treeToValue(typed,SnapshotParameters.class);
            case "observe" -> json.treeToValue(typed,ObserveParameters.class);
            case "console" -> json.treeToValue(typed,ConsoleParameters.class);
            case "network" -> json.treeToValue(typed,NetworkParameters.class);
            case "debug" -> json.treeToValue(typed,DebugParameters.class);
            case "get-html" -> json.treeToValue(typed,GetHtmlParameters.class);
            case "evaluate" -> json.treeToValue(typed,EvaluateParameters.class);
            case "emulate" -> json.treeToValue(typed,EmulateParameters.class);
            case "wheel" -> json.treeToValue(typed,WheelParameters.class);
            case "scroll-to" -> json.treeToValue(typed,ScrollToParameters.class);
            case "wait-for-navigation" -> json.treeToValue(typed,WaitForNavigationParameters.class);
            case "wait-ms" -> json.treeToValue(typed,WaitMsParameters.class);
            case "request-help" -> json.treeToValue(typed,RequestHelpParameters.class);
            case "click" -> json.treeToValue(typed,ClickParameters.class);
            case "hover" -> json.treeToValue(typed,HoverParameters.class);
            case "focus" -> json.treeToValue(typed,FocusParameters.class);
            case "blur" -> json.treeToValue(typed,BlurParameters.class);
            case "fill" -> json.treeToValue(typed,FillParameters.class);
            case "press" -> json.treeToValue(typed,PressParameters.class);
            case "select" -> json.treeToValue(typed,SelectParameters.class);
            case "tab-list" -> json.treeToValue(typed,TabListParameters.class);
            case "tab-create" -> json.treeToValue(typed,TabCreateParameters.class);
            case "tab-close" -> json.treeToValue(typed,TabCloseParameters.class);
            case "tab-select" -> json.treeToValue(typed,TabSelectParameters.class);
            case "tab-borrow" -> json.treeToValue(typed,TabBorrowParameters.class);
            case "tab-return" -> json.treeToValue(typed,TabReturnParameters.class);
            case "window-resize" -> json.treeToValue(typed,WindowResizeParameters.class);
            case "record-start" -> json.treeToValue(typed,RecordStartParameters.class);
            case "record-stop" -> json.treeToValue(typed,RecordStopParameters.class);
            case "start" -> json.treeToValue(typed,StartParameters.class);
            case "stop" -> json.treeToValue(typed,StopParameters.class);
            default -> throw new IllegalArgumentException("browser_operation_not_supported");
        };
    }
